pragma solidity ^0.8.20;

import {C} from "contracts/C.sol";
import {ReentrancyGuard} from "contracts/beanstalk/ReentrancyGuard.sol";
import {LibDibbler} from "contracts/libraries/LibDibbler.sol";

abstract contract PodTransfer is ReentrancyGuard {
    event PlotTransfer(
        address indexed from,
        address indexed to,
        uint256 fieldId,
        uint256 indexed index,
        uint256 amount
    );

    event PodApproval(
        address indexed owner,
        address indexed spender,
        uint256 fieldId,
        uint256 amount
    );

    /**
     * Internal
     **/

    function _transferPlot(
        address from,
        address to,
        uint256 fieldId,
        uint256 index,
        uint256 start,
        uint256 amount
    ) internal {
        require(from != to, "Field: Cannot transfer Pods to oneself.");
        require(amount > 0, "Marketplace: amount must be > 0.");
        LibDibbler.insertPlot(to, fieldId, index + start, amount);
        removePlot(from, fieldId, index, start, amount + start);
        emit PlotTransfer(from, to, fieldId, index + start, amount);
    }

    function removePlot(
        address account,
        uint256 fieldId,
        uint256 index,
        uint256 start,
        uint256 end
    ) internal {
        uint256 amountAfterEnd = s.accts[account].fields[fieldId].plots[index] - end;

        if (start > 0) {
            s.accts[account].fields[fieldId].plots[index] = start;
        } else {
            delete s.accts[account].fields[fieldId].plots[index];
            LibDibbler.removePlotIndexFromAccount(account, fieldId, index);
        }

        if (amountAfterEnd > 0) {
            uint256 newIndex = index + end;
            s.accts[account].fields[fieldId].plots[newIndex] = amountAfterEnd;
            s.accts[account].fields[fieldId].plotIndexes.push(newIndex);
            s.accts[account].fields[fieldId].piIndex[newIndex] =
                s.accts[account].fields[fieldId].plotIndexes.length -
                1;
        }
    }

    function decrementAllowancePods(
        address owner,
        address spender,
        uint256 fieldId,
        uint256 amount
    ) internal {
        uint256 currentAllowance = _getAllowancePods(owner, spender, fieldId);
        if (currentAllowance < amount || currentAllowance == 0) {
            revert("Field: Insufficient approval.");
        }
        setAllowancePods(owner, spender, fieldId, currentAllowance - amount);
    }

    function setAllowancePods(
        address owner,
        address spender,
        uint256 fieldId,
        uint256 amount
    ) internal {
        s.accts[owner].fields[fieldId].podAllowances[spender] = amount;
    }

    /**
     * @notice Checks and decrements allowance if spender is not the owner.
     * @dev Helper function to reduce stack depth in transfer functions.
     */
    function _checkAndDecrementAllowance(
        address owner,
        address spender,
        uint256 fieldId,
        uint256 amount
    ) internal {
        if (spender != owner) {
            uint256 allowance = _getAllowancePods(owner, spender, fieldId);
            if (allowance != type(uint256).max) {
                decrementAllowancePods(owner, spender, fieldId, amount);
            }
        }
    }

    function _getAllowancePods(
        address owner,
        address spender,
        uint256 fieldId
    ) internal view returns (uint256) {
        return s.accts[owner].fields[fieldId].podAllowances[spender];
    }
}

